import{_ as e,o,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Busca nos campos de seleção","description":"","frontmatter":{"title":"Busca nos campos de seleção","id":"eproc-filtro-selects","plataforma":"eproc","grupo":"Pesquisa e filtros","plano":"free","desde":"1.8.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-filtro-selects"}]]},"headers":[],"relativePath":"funcionalidades/eproc-filtro-selects.md","filePath":"funcionalidades/eproc-filtro-selects.md"}'),t={name:"funcionalidades/eproc-filtro-selects.md"};function l(i,a,c,d,p,n){return o(),s("div",null,a[0]||(a[0]=[r('<h1 id="busca-nos-campos-de-selecao" tabindex="-1">Busca nos campos de seleção <a class="header-anchor" href="#busca-nos-campos-de-selecao" aria-label="Permalink to &quot;Busca nos campos de seleção&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Muitas listas de opções do eproc (tipo de parte, classe, órgão e outras) não têm busca. Com este recurso, ao abrir uma dessas listas aparece um campo para filtrá-la por trechos, em qualquer ordem. A estrela ao lado de cada opção a favorita, fixando-a no topo daquela lista.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, em qualquer campo de seleção sem busca própria que tenha opções suficientes (8 ou mais, por padrão).</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Clique no campo de seleção. No lugar da lista comum, abre um painel com campo de busca.</li><li>Digite trechos do que procura. Com a lista ainda fechada, basta começar a digitar com o campo selecionado.</li><li>Escolha a opção.</li><li>Para favoritar uma opção, clique na estrela ao lado dela. Na próxima vez, ela aparece no topo daquela lista. Clique de novo para desfavoritar.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Mínimo de opções para mostrar a busca</td><td>8</td><td>Listas menores continuam com a lista comum (de 2 a 100).</td></tr><tr><td>Busca aproximada (tolera abreviações e pequenos erros de digitação, mostrando primeiro os resultados mais relevantes)</td><td>ligada</td><td>Também encontra opções com pequenas diferenças de grafia.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Não vale para listas de várias escolhas, listas sempre abertas nem campos que já têm busca própria.</li><li>O campo &quot;Novo localizador&quot; tem recurso próprio: <a href="./eproc-filtro-novo-localizador">Filtro por trechos no campo de novo localizador</a>.</li><li>Os favoritos são lembrados pelo campo e pelo texto da opção. Se o eproc mudar o texto da opção, ela deixa de aparecer como favorita.</li></ul>',11)]))}const h=e(t,[["render",l]]);export{m as __pageData,h as default};
